visible.script:
let count = 0, firstClickTime;
let doubleClickFrameTime = 500; //milliseconds
export function cursorClick(event) {


    count++;
    if (count % 2 !== 0) //if count of clicks is odd number (1, 3, 5)
    {
        firstClickTime = Date.now(); //remember time when clicked
    }
    if (count % 2 === 0) //if amount of clicks is even number (2, 4, 6)
    {
        if (Date.now() - firstClickTime > doubleClickFrameTime) //if amount of time from first click to second is more than expected time frame for double click
        {
            firstClickTime = Date.now(); //remember new time
            count--; //-1 click
        }
        else //click is in expected time frame for double click
        {
           if (thisScene.getLayer("拉毗台词.mp3").stop){
			   thisScene.getLayer("拉毗台词.mp3").play();
		   }
		   else thisScene.getLayer("拉毗台词.mp3").stop();

            count = 0; //reset click count
        }
    }
}
